<script setup>import AppShell from'../Layouts/AppShell.vue';import PageHeader from'../Components/PageHeader.vue';import UiButton from'../Components/UiButton.vue';import UiCard from'../Components/UiCard.vue';import{Head,useForm}from'@inertiajs/vue3';defineProps({step:String,user:Object});const role=useForm({role:'photographer'}),profile=useForm({first_name:'',last_name:'',company_name:'',email:''});</script><template><AppShell><Head title="Onboarding"/><div class="lp-page-narrow"><PageHeader eyebrow="Studio setup" title="Shape your LensPic workspace" description="A short setup keeps your workspace and delivery experience relevant."/><UiCard class="mt-8"><template v-if="step==='role'"><h2 class="text-xl font-bold">How will you use LensPic?</h2><div class="mt-5 grid gap-4 sm:grid-cols-2"><button v-for="r in ['photographer','user']" :key="r" :aria-pressed="role.role===r" :class="['rounded-2xl border p-6 text-left',role.role===r?'border-indigo bg-indigo/5':'border-slate-200 hover:border-slate-300']" @click="role.role=r"><b class="capitalize">{{r}}</b><p class="mt-2 text-sm text-slate-600">{{r==='photographer'?'Create Groups and deliver galleries.':'Join Groups and discover your photos.'}}</p></button></div><UiButton class="mt-6" :loading="role.processing" @click="role.post('/onboarding/account-type')">Continue</UiButton></template><template v-else><h2 class="text-xl font-bold">Complete your studio profile</h2><div class="mt-5 grid gap-4 sm:grid-cols-2"><input v-model="profile.first_name" class="field" placeholder="First name"><input v-model="profile.last_name" class="field" placeholder="Last name"></div><input v-model="profile.company_name" class="field mt-4" placeholder="Studio name"><input v-model="profile.email" class="field mt-4" type="email" placeholder="Studio email"><UiButton class="mt-6" :loading="profile.processing" @click="profile.post('/onboarding/profile')">Finish setup</UiButton></template></UiCard></div></AppShell></template>
